body:
Jira Link: [DB-14254](https://yugabyte.atlassian.net/browse/DB-14254)
### Description

* Parallel Seq Scan stops kicking in when SeqScan hint is specified.
* On the other hand, I can get Parallel Seq Scan with`Set(enable_indexscan off)` hint or `set enable_indexscan=off;` GUC flag setting in the test case shown below.
* No problem with IndexScan and IndexOnlyScan hints.
* Reproducible on recent master (976e9b2460c6990eaf2a7b4185ae9e121a203f32).

```
select version();
                                                             version                                                             
---------------------------------------------------------------------------------------------------------------------------------
 PostgreSQL 15.2-YB-2.25.0.0-b0 on x86_64-apple-darwin23.6.0, compiled by Apple clang version 16.0.0 (clang-1600.0.26.4), 64-bit
(1 row)

\c yugabyte
You are now connected to database "yugabyte" as user "yugabyte".
drop database colocateddb;
ysqlsh:bug.sql:4: ERROR:  database "colocateddb" does not exist
create database colocateddb with colocation=on;
CREATE DATABASE
\c colocateddb
You are now connected to database "colocateddb" as user "yugabyte".
create table t1 (c1 int, c2 char(8192), primary key(c1 asc));
CREATE TABLE
insert into t1 select i, lpad(i::bpchar, 8192) from generate_series(1, 100000) i;
INSERT 0 100000
analyze t1;
ANALYZE
set yb_enable_optimizer_statistics=ON;
SET
set yb_enable_base_scans_cost_model=ON;
SET
set yb_parallel_range_rows=10000;
SET
explain select c1 from t1 where c1 <= 1000;
                                       QUERY PLAN                                       
----------------------------------------------------------------------------------------
 Gather  (cost=1180.00..2210.60 rows=963 width=4)
   Workers Planned: 2
   ->  Parallel Index Scan using t1_pkey on t1  (cost=180.00..1114.30 rows=401 width=4)
         Index Cond: (c1 <= 1000)
(4 rows)

/*+ SeqScan(t1) */explain select c1 from t1 where c1 <= 1000;
                        QUERY PLAN                        
----------------------------------------------------------
 Seq Scan on t1  (cost=180.00..81201.05 rows=963 width=4)
   Storage Filter: (c1 <= 1000)
(2 rows)

/*+ Set(enable_indexscan off) */explain select c1 from t1 where c1 <= 1000;
                               QUERY PLAN                                
-------------------------------------------------------------------------
 Gather  (cost=1180.00..35035.07 rows=963 width=4)
   Workers Planned: 2
   ->  Parallel Seq Scan on t1  (cost=180.00..33938.77 rows=401 width=4)
         Storage Filter: (c1 <= 1000)
(4 rows)

/*+ IndexOnlyScan(t1) */explain select c1 from t1 where c1 <= 1000;
                                       QUERY PLAN                                       
----------------------------------------------------------------------------------------
 Gather  (cost=1180.00..2210.60 rows=963 width=4)
   Workers Planned: 2
   ->  Parallel Index Scan using t1_pkey on t1  (cost=180.00..1114.30 rows=401 width=4)
         Index Cond: (c1 <= 1000)
(4 rows)

/*+ IndexScan(t1) */explain select c1 from t1 where c1 <= 1000;
                                       QUERY PLAN                                       
----------------------------------------------------------------------------------------
 Gather  (cost=1180.00..2210.60 rows=963 width=4)
   Workers Planned: 2
   ->  Parallel Index Scan using t1_pkey on t1  (cost=180.00..1114.30 rows=401 width=4)
         Index Cond: (c1 <= 1000)
(4 rows)
```

Test Case
---
```
select version();

\c yugabyte
drop database colocateddb;

create database colocateddb with colocation=on;
\c colocateddb

create table t1 (c1 int, c2 char(8192), primary key(c1 asc));
insert into t1 select i, lpad(i::bpchar, 8192) from generate_series(1, 100000) i;
analyze t1;


set yb_enable_optimizer_statistics=ON;
set yb_enable_base_scans_cost_model=ON;

set yb_parallel_range_rows=10000;

explain select c1 from t1 where c1 <= 1000;
/*+ SeqScan(t1) */explain select c1 from t1 where c1 <= 1000;
/*+ Set(enable_indexscan off) */explain select c1 from t1 where c1 <= 1000;
/*+ IndexOnlyScan(t1) */explain select c1 from t1 where c1 <= 1000;
/*+ IndexScan(t1) */explain select c1 from t1 where c1 <= 1000;
```

